values ('50000000-0000-4000-8000-000000000001', 'coktan_secmeli', 'Birim karelere çizilmiş, aynı doğrultudaki $\vec{K}$ ve $\vec{L}$ vektörleri şekilde verilmiştir. $\vec{K} + \vec{L} + \vec{M} = 0$ olması için $\vec{M}$ vektörü nasıl olmalıdır?', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 222" role="img" aria-label="Birim karelere çizilmiş K ve L vektörleri."><rect x="26" y="20" width="468" height="180" fill="#fbfcfe"/><line x1="26" y1="20" x2="26" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="62" y1="20" x2="62" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="98" y1="20" x2="98" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="134" y1="20" x2="134" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="170" y1="20" x2="170" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="206" y1="20" x2="206" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="242" y1="20" x2="242" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="278" y1="20" x2="278" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="314" y1="20" x2="314" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="350" y1="20" x2="350" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="386" y1="20" x2="386" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="422" y1="20" x2="422" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="458" y1="20" x2="458" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="494" y1="20" x2="494" y2="200" stroke="#d5dbe3" stroke-width="1"/><line x1="26" y1="20" x2="494" y2="20" stroke="#d5dbe3" stroke-width="1"/><line x1="26" y1="56" x2="494" y2="56" stroke="#d5dbe3" stroke-width="1"/><line x1="26" y1="92" x2="494" y2="92" stroke="#d5dbe3" stroke-width="1"/><line x1="26" y1="128" x2="494" y2="128" stroke="#d5dbe3" stroke-width="1"/><line x1="26" y1="164" x2="494" y2="164" stroke="#d5dbe3" stroke-width="1"/><line x1="26" y1="200" x2="494" y2="200" stroke="#d5dbe3" stroke-width="1"/><g data-ciz-adim="0" data-ciz-sure="700"><line x1="62" y1="56" x2="194" y2="56" stroke="#1f5fae" stroke-width="3.5" stroke-linecap="round"/><polygon points="206,56 193,61.85 193,50.15" fill="#1f5fae"/></g><g><text x="134" y="46" font-size="18" text-anchor="middle" fill="#1f5fae" font-weight="700" font-style="italic" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">K</text><line x1="127" y1="27" x2="140" y2="27" stroke="#1f5fae" stroke-width="1.6"/><polygon points="143,27 138,24 138,30" fill="#1f5fae"/></g><g data-ciz-adim="0" data-ciz-sure="900" data-ciz-gecikme="500"><line x1="386" y1="92" x2="182" y2="92" stroke="#c62828" stroke-width="3.5" stroke-linecap="round"/><polygon points="170,92 183,86.15 183,97.85" fill="#c62828"/></g><g><text x="278" y="82" font-size="18" text-anchor="middle" fill="#c62828" font-weight="700" font-style="italic" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">L</text><line x1="271" y1="63" x2="284" y2="63" stroke="#c62828" stroke-width="1.6"/><polygon points="287,63 282,60 282,66" fill="#c62828"/></g><g data-ciz-adim="2" data-ciz-sure="700"><line x1="170" y1="164" x2="110" y2="164" stroke="#6a3fb5" stroke-width="3.5" stroke-linecap="round" stroke-dasharray="7 5"/><polygon points="98,164 111,158.15 111,169.85" fill="#6a3fb5"/></g><text x="134" y="152" font-size="16" text-anchor="middle" fill="#6a3fb5" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round" data-ciz-adim="2" data-ciz-gecikme="500">K + L</text><g data-ciz-adim="3" data-ciz-sure="700"><line x1="350" y1="164" x2="410" y2="164" stroke="#1b7a43" stroke-width="3.5" stroke-linecap="round"/><polygon points="422,164 409,169.85 409,158.15" fill="#1b7a43"/></g><g data-ciz-adim="3" data-ciz-gecikme="500"><text x="386" y="154" font-size="18" text-anchor="middle" fill="#1b7a43" font-weight="700" font-style="italic" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">M</text><line x1="379" y1="135" x2="392" y2="135" stroke="#1b7a43" stroke-width="1.6"/><polygon points="395,135 390,132 390,138" fill="#1b7a43"/></g><text x="460" y="217" font-size="13" text-anchor="middle" fill="#6b7685" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">1 birim</text><line x1="458" y1="204" x2="494" y2="204" stroke="#6b7685" stroke-width="1.4"/></svg>', '[{"harf":"A","metin":"2 birim, sağa doğru"},{"harf":"B","metin":"2 birim, sola doğru"},{"harf":"C","metin":"10 birim, sağa doğru"},{"harf":"D","metin":"10 birim, sola doğru"},{"harf":"E","metin":"6 birim, sağa doğru"}]'::jsonb, 'A',
  '[{"metin":"Sağ yönü pozitif seçelim. $\\vec{K}$ vektörü +4 birim, $\\vec{L}$ vektörü −6 birimdir."},{"metin":"$\\vec{K} + \\vec{L} = (+4) + (-6) = -2$ birim, yani bileşke 2 birim sola doğrudur."},{"metin":"Toplamın sıfır olması için $\\vec{M}$ bu bileşkeyle eşit büyüklükte ve zıt yönde olmalıdır: 2 birim, sağa doğru. Cevap A."}]'::jsonb, 2, false, 'Örnek soru.', true)
