values ('50000000-0000-4000-8000-000000000002', 'dogru_yanlis', 'Bir koşucu, 400 m uzunluğundaki kapalı bir pistte başlangıç çizgisinden koşmaya başlıyor ve bir tur atarak aynı çizgide duruyor. Bu koşucunun yer değiştirmesinin büyüklüğü, aldığı yola eşittir.', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 250" role="img" aria-label="Kapalı koşu pisti ve başlangıç çizgisi."><defs>
    <radialGradient id="q2-kosucu" cx="35%" cy="35%" r="70%"><stop offset="0" stop-color="#ffb37a"/><stop offset="1" stop-color="#c2410c"/></radialGradient>
    <linearGradient id="q2-cim" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6fbf73"/><stop offset="1" stop-color="#3f8f4a"/></linearGradient>
  </defs><path d="M260 200 H167 A80 80 0 0 1 167 40 H353 A80 80 0 0 1 353 200 Z" fill="none" stroke="#b5532f" stroke-width="44" stroke-linejoin="round"/><path d="M260 200 H167 A80 80 0 0 1 167 40 H353 A80 80 0 0 1 353 200 Z" fill="none" stroke="#c9653f" stroke-width="40" stroke-linejoin="round"/><path d="M167 62 H353 A58 58 0 0 1 353 178 H167 A58 58 0 0 1 167 62 Z" fill="url(#q2-cim)" stroke="#ffffff" stroke-width="2"/><path d="M260 200 H167 A80 80 0 0 1 167 40 H353 A80 80 0 0 1 353 200 Z" fill="none" stroke="#ffffff" stroke-width="1.5" stroke-dasharray="10 8" opacity="0.8"/><path d="M167 18 H353 A102 102 0 0 1 353 222 H167 A102 102 0 0 1 167 18 Z" fill="none" stroke="#ffffff" stroke-width="2"/><line x1="260" y1="178" x2="260" y2="222" stroke="#ffffff" stroke-width="5"/><text x="260" y="244" font-size="14" text-anchor="middle" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">Başlangıç ve bitiş çizgisi</text><path id="q2-yol" d="M260 200 H167 A80 80 0 0 1 167 40 H353 A80 80 0 0 1 353 200 Z" fill="none" stroke="none"/><circle cx="0" cy="0" r="10" fill="url(#q2-kosucu)" stroke="#7c2d12" stroke-width="1.5" transform="translate(260 200)" data-ciz-adim="1" data-ciz-tur="hareket" data-ciz-yol="q2-yol" data-ciz-sure="2600"/><text x="260" y="125" font-size="17" text-anchor="middle" fill="#1d2733" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round" data-ciz-adim="1" data-ciz-gecikme="2600">Alınan yol: 400 m</text><text x="260" y="150" font-size="17" text-anchor="middle" fill="#c62828" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round" data-ciz-adim="2">Yer değiştirme: 0 m</text></svg>', null, 'Y',
  '[{"metin":"Alınan yol skaler bir niceliktir ve izlenen yolun uzunluğudur: 400 m."},{"metin":"Yer değiştirme vektörel bir niceliktir; başlangıç noktasından bitiş noktasına çizilen vektördür. Koşucu başladığı yerde durduğu için yer değiştirme sıfırdır."},{"metin":"400 m ile sıfır eşit olmadığından ifade yanlıştır."}]'::jsonb, 2, true, 'Örnek soru.', true)
