values ('50000000-0000-4000-8000-000000000004', 'coktan_secmeli', 'Düz bir yolda aynı doğrultuda hareket eden K ve L araçlarının konum-zaman grafikleri şekildeki gibidir. Araçlar hangi konumda yan yana gelir?', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 310" role="img" aria-label="K ve L araçlarının konum-zaman grafiği."><line x1="250" y1="270" x2="250" y2="170" stroke="#6b7685" stroke-width="1.4" stroke-dasharray="5 4"/><line x1="430" y1="270" x2="430" y2="70" stroke="#6b7685" stroke-width="1.4" stroke-dasharray="5 4"/><line x1="70" y1="170" x2="430" y2="170" stroke="#6b7685" stroke-width="1.4" stroke-dasharray="5 4"/><line x1="70" y1="70" x2="430" y2="70" stroke="#6b7685" stroke-width="1.4" stroke-dasharray="5 4"/><g><line x1="70" y1="270" x2="460" y2="270" stroke="#1d2733" stroke-width="2" stroke-linecap="round"/><polygon points="470,270 459,274.95 459,265.05" fill="#1d2733"/></g><g><line x1="70" y1="270" x2="70" y2="44" stroke="#1d2733" stroke-width="2" stroke-linecap="round"/><polygon points="70,34 74.95,45 65.05,45" fill="#1d2733"/></g><text x="80" y="40" font-size="15" text-anchor="start" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">x (m)</text><text x="476" y="275" font-size="15" text-anchor="start" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">t (s)</text><text x="62" y="288" font-size="14" text-anchor="end" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">0</text><text x="250" y="290" font-size="14" text-anchor="middle" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">3</text><text x="430" y="290" font-size="14" text-anchor="middle" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">6</text><text x="62" y="175" font-size="14" text-anchor="end" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">30</text><text x="62" y="75" font-size="14" text-anchor="end" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">60</text><line x1="70" y1="270" x2="430" y2="70" stroke="#1f5fae" stroke-width="4" stroke-linecap="round" data-ciz-adim="0" data-ciz-sure="900"/><line x1="70" y1="70" x2="430" y2="170" stroke="#c62828" stroke-width="4" stroke-linecap="round" data-ciz-adim="0" data-ciz-sure="900" data-ciz-gecikme="400"/><text x="442" y="76" font-size="18" text-anchor="start" fill="#1f5fae" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">K</text><text x="442" y="176" font-size="18" text-anchor="start" fill="#c62828" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">L</text><g data-ciz-adim="3"><line x1="310" y1="270" x2="310" y2="136.67" stroke="#1b7a43" stroke-width="1.4" stroke-dasharray="5 4"/><line x1="70" y1="136.67" x2="310" y2="136.67" stroke="#1b7a43" stroke-width="1.4" stroke-dasharray="5 4"/><circle cx="310" cy="136.66666666666666" r="7" fill="#1b7a43" stroke="#fff" stroke-width="2"/><text x="310" y="290" font-size="14" text-anchor="middle" fill="#1b7a43" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">4</text><text x="62" y="141.67" font-size="14" text-anchor="end" fill="#1b7a43" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">40</text></g></svg>', '[{"harf":"A","metin":"20 m"},{"harf":"B","metin":"30 m"},{"harf":"C","metin":"40 m"},{"harf":"D","metin":"45 m"},{"harf":"E","metin":"50 m"}]'::jsonb, 'C',
  '[{"metin":"Konum-zaman grafiğinin eğimi hızı verir: $\\vartheta_K = \\dfrac{60 - 0}{6} = 10$ m/s, $\\vartheta_L = \\dfrac{30 - 60}{6} = -5$ m/s."},{"metin":"Konum denklemleri: $x_K = 10t$ ve $x_L = 60 - 5t$."},{"metin":"Yan yana gelmek için konumlar eşit olmalıdır: $10t = 60 - 5t$, buradan $t = 4$ s ve $x = 40$ m. Cevap C."}]'::jsonb, 3, false, 'Örnek soru.', true)
