insert into public.soru (id, tur, govde, sekil_svg, secenekler, dogru_cevap, cozum_adimlari, zorluk, baglam_temelli, kaynak_notu, ornek)
values ('50000000-0000-4000-8000-000000000005', 'acik_uclu', 'Düz bir yolda durgun hâlden harekete geçen bir otomobilin hız-zaman grafiği şekildeki gibidir.<br>a) Otomobilin 0-4 s, 4-8 s ve 8-10 s aralıklarındaki ivmelerini bulunuz.<br>b) Otomobilin 10 s boyunca aldığı yolu bulunuz.', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 290" role="img" aria-label="Otomobilin hız-zaman grafiği."><g data-ciz-adim="3" data-ciz-sure="600"><polygon points="70,250 222,90 222,250" fill="#1f5fae" fill-opacity="0.16"/><polygon points="222,250 222,90 374,90 374,250" fill="#1b7a43" fill-opacity="0.16"/><polygon points="374,250 374,90 450,250" fill="#d9611c" fill-opacity="0.2"/><text x="171.33" y="203.33" font-size="15" text-anchor="middle" fill="#1f5fae" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">24 m</text><text x="298" y="183.33" font-size="15" text-anchor="middle" fill="#1b7a43" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">48 m</text><text x="399" y="220.67" font-size="15" text-anchor="middle" fill="#d9611c" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">12 m</text></g><line x1="222" y1="250" x2="222" y2="90" stroke="#6b7685" stroke-width="1.4" stroke-dasharray="5 4"/><line x1="374" y1="250" x2="374" y2="90" stroke="#6b7685" stroke-width="1.4" stroke-dasharray="5 4"/><line x1="70" y1="90" x2="222" y2="90" stroke="#6b7685" stroke-width="1.4" stroke-dasharray="5 4"/><g><line x1="70" y1="250" x2="460" y2="250" stroke="#1d2733" stroke-width="2" stroke-linecap="round"/><polygon points="470,250 459,254.95 459,245.05" fill="#1d2733"/></g><g><line x1="70" y1="250" x2="70" y2="44" stroke="#1d2733" stroke-width="2" stroke-linecap="round"/><polygon points="70,34 74.95,45 65.05,45" fill="#1d2733"/></g><text x="80" y="40" font-size="15" text-anchor="start" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">ϑ (m/s)</text><text x="476" y="255" font-size="15" text-anchor="start" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">t (s)</text><text x="62" y="268" font-size="14" text-anchor="end" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">0</text><text x="222" y="270" font-size="14" text-anchor="middle" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">4</text><text x="374" y="270" font-size="14" text-anchor="middle" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">8</text><text x="450" y="270" font-size="14" text-anchor="middle" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">10</text><text x="62" y="95" font-size="14" text-anchor="end" fill="#1d2733" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">12</text><polyline points="70,250 222,90 374,90 450,250" fill="none" stroke="#1d2733" stroke-width="4" stroke-linejoin="round" stroke-linecap="round" data-ciz-adim="0" data-ciz-sure="1200"/><line x1="70" y1="250" x2="222" y2="90" stroke="#1f5fae" stroke-width="7" stroke-linecap="round" stroke-opacity="0.85" data-ciz-adim="1" data-ciz-sure="700"/><line x1="222" y1="90" x2="374" y2="90" stroke="#1b7a43" stroke-width="7" stroke-linecap="round" stroke-opacity="0.85" data-ciz-adim="2" data-ciz-sure="600"/><line x1="374" y1="90" x2="450" y2="250" stroke="#d9611c" stroke-width="7" stroke-linecap="round" stroke-opacity="0.85" data-ciz-adim="2" data-ciz-sure="500" data-ciz-gecikme="600"/></svg>', null, 'a) 3 m/s², 0 ve −6 m/s². b) 84 m.',
  '[{"metin":"İvme, hız-zaman grafiğinin eğimidir. 0-4 s: $a = \\dfrac{12 - 0}{4} = 3$ m/s²."},{"metin":"4-8 s aralığında hız değişmez, $a = 0$. 8-10 s: $a = \\dfrac{0 - 12}{2} = -6$ m/s²; eksi işaret ivmenin hareket yönüne zıt olduğunu gösterir."},{"metin":"Alınan yol, grafiğin altında kalan alandır: $\\dfrac{4 \\times 12}{2} + 4 \\times 12 + \\dfrac{2 \\times 12}{2} = 24 + 48 + 12 = 84$ m."}]'::jsonb, 4, false, 'Örnek soru.', true)
on conflict (id) do update set tur = excluded.tur, govde = excluded.govde, sekil_svg = excluded.sekil_svg,
