insert into public.soru (id, tur, govde, sekil_svg, secenekler, dogru_cevap, cozum_adimlari, zorluk, baglam_temelli, kaynak_notu, ornek)
values ('50000000-0000-4000-8000-000000000006', 'coktan_secmeli', 'Düz bir yolda 20 m/s hızla giden bir otobüsün sürücüsü, ileride yaya geçidini görünce fren yapıyor. Otobüs aynı yönde ilerlemeye devam ederken hızı 4 s içinde düzgün olarak 8 m/s değerine düşüyor. Bu süre boyunca otobüsün ivmesinin büyüklüğü ve yönü nedir?', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 215" role="img" aria-label="Yaya geçidine yaklaşırken fren yapan otobüs."><defs>
    <linearGradient id="q6-govde" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffd76a"/><stop offset="0.55" stop-color="#f5b81f"/><stop offset="1" stop-color="#c98a06"/></linearGradient>
    <linearGradient id="q6-cam" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#d9ecfb"/><stop offset="1" stop-color="#7fb2dc"/></linearGradient>
    <radialGradient id="q6-jant" cx="40%" cy="40%" r="70%"><stop offset="0" stop-color="#f1f3f5"/><stop offset="1" stop-color="#8a939c"/></radialGradient>
    <linearGradient id="q6-yol" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6b7178"/><stop offset="1" stop-color="#474c52"/></linearGradient>
  </defs><rect x="0" y="160" width="520" height="55" fill="url(#q6-yol)"/><line x1="0" y1="190" x2="428" y2="190" stroke="#f4f4f4" stroke-width="3" stroke-dasharray="26 18"/><rect x="440" y="163" width="8" height="49" fill="#f4f4f4"/><rect x="455" y="163" width="8" height="49" fill="#f4f4f4"/><rect x="470" y="163" width="8" height="49" fill="#f4f4f4"/><rect x="485" y="163" width="8" height="49" fill="#f4f4f4"/><rect x="500" y="163" width="8" height="49" fill="#f4f4f4"/><ellipse cx="240" cy="171" rx="105" ry="6" fill="#000" opacity="0.25"/><path d="M140 150 V82 Q140 68 154 68 H318 Q336 68 340 86 L346 120 V150 Z" fill="url(#q6-govde)" stroke="#8a5a00" stroke-width="2"/><rect x="154" y="80" width="32" height="30" rx="4" fill="url(#q6-cam)" stroke="#5e7d96"/><rect x="192" y="80" width="32" height="30" rx="4" fill="url(#q6-cam)" stroke="#5e7d96"/><rect x="230" y="80" width="32" height="30" rx="4" fill="url(#q6-cam)" stroke="#5e7d96"/><rect x="268" y="80" width="32" height="30" rx="4" fill="url(#q6-cam)" stroke="#5e7d96"/><path d="M306 80 H322 Q330 80 332 88 L337 112 H306 Z" fill="url(#q6-cam)" stroke="#5e7d96"/><rect x="140" y="124" width="206" height="6" fill="#8a5a00" opacity="0.35"/><rect x="340" y="128" width="8" height="10" rx="2" fill="#fff6c9" stroke="#8a5a00"/><circle cx="184" cy="152" r="18" fill="#22262b"/><circle cx="184" cy="152" r="8" fill="url(#q6-jant)"/><circle cx="298" cy="152" r="18" fill="#22262b"/><circle cx="298" cy="152" r="8" fill="url(#q6-jant)"/><g data-ciz-adim="0" data-ciz-sure="600"><line x1="180" y1="44" x2="288" y2="44" stroke="#1f5fae" stroke-width="3.5" stroke-linecap="round"/><polygon points="300,44 287,49.85 287,38.15" fill="#1f5fae"/></g><text x="240" y="30" font-size="16" text-anchor="middle" fill="#1f5fae" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">ϑ = 20 m/s</text><g data-ciz-adim="3" data-ciz-sure="500"><line x1="410" y1="110" x2="374" y2="110" stroke="#c62828" stroke-width="3.5" stroke-linecap="round"/><polygon points="362,110 375,104.15 375,115.85" fill="#c62828"/></g><text x="386" y="96" font-size="18" text-anchor="middle" fill="#c62828" font-weight="700" font-style="italic" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round" data-ciz-adim="3" data-ciz-gecikme="300">a</text></svg>', '[{"harf":"A","metin":"3 m/s², hareket yönünde","gerekce":"Büyüklük doğru ama otobüs yavaşlıyor. Hız azalıyorsa ivme hareket yönüne zıttır."},{"harf":"B","metin":"3 m/s², hareket yönüne zıt"},{"harf":"C","metin":"5 m/s², hareket yönüne zıt","gerekce":"20 m/s yalnızca ilk hızdır. İvme hız değişimidir: (8 − 20) / 4. Son hızı hesaba katmak gerekir."},{"harf":"D","metin":"7 m/s², hareket yönünde","gerekce":"Hızlar toplanmış: (20 + 8) / 4 = 7. İvme hızların toplamıyla değil, farkıyla bulunur."},{"harf":"E","metin":"2 m/s², hareket yönüne zıt","gerekce":"Yalnızca son hız süreye bölünmüş: 8 / 4. İvme için hız değişimi kullanılır."}]'::jsonb, 'B',
  '[{"metin":"Hareket yönünü pozitif seçelim. Hız değişimi $\\Delta\\vartheta = 8 - 20 = -12$ m/s."},{"metin":"$a = \\dfrac{\\Delta\\vartheta}{\\Delta t} = \\dfrac{-12}{4} = -3$ m/s²."},{"metin":"İvmenin büyüklüğü 3 m/s²; eksi işaret, ivmenin hareket yönüne zıt olduğunu gösterir. Otobüs bu yüzden yavaşlar. Cevap B."}]'::jsonb, 3, true, 'Örnek soru.', true)
on conflict (id) do update set tur = excluded.tur, govde = excluded.govde, sekil_svg = excluded.sekil_svg,
  secenekler = excluded.secenekler, dogru_cevap = excluded.dogru_cevap, cozum_adimlari = excluded.cozum_adimlari,
  zorluk = excluded.zorluk, baglam_temelli = excluded.baglam_temelli, kaynak_notu = excluded.kaynak_notu, ornek = excluded.ornek;
