values ('50000000-0000-4000-8000-000000000009', 'coktan_secmeli', 'Sürtünmesiz yatay düzlemde kütleleri sırasıyla 2 kg ve 3 kg olan K ve L blokları, kütlesi önemsenmeyen gergin bir iple birbirine bağlıdır. L bloğuna yatay ve 20 N büyüklüğünde $\vec{F}$ kuvveti şekildeki gibi uygulanıyor. İpteki gerilme kuvvetinin büyüklüğü kaç N olur?', '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 170" role="img" aria-label="Sürtünmesiz düzlemde iple bağlı K ve L blokları."><line x1="40" y1="140" x2="490" y2="140" stroke="#1d2733" stroke-width="2.5"/><line x1="46" y1="142" x2="36" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="60" y1="142" x2="50" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="74" y1="142" x2="64" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="88" y1="142" x2="78" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="102" y1="142" x2="92" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="116" y1="142" x2="106" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="130" y1="142" x2="120" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="144" y1="142" x2="134" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="158" y1="142" x2="148" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="172" y1="142" x2="162" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="186" y1="142" x2="176" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="200" y1="142" x2="190" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="214" y1="142" x2="204" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="228" y1="142" x2="218" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="242" y1="142" x2="232" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="256" y1="142" x2="246" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="270" y1="142" x2="260" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="284" y1="142" x2="274" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="298" y1="142" x2="288" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="312" y1="142" x2="302" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="326" y1="142" x2="316" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="340" y1="142" x2="330" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="354" y1="142" x2="344" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="368" y1="142" x2="358" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="382" y1="142" x2="372" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="396" y1="142" x2="386" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="410" y1="142" x2="400" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="424" y1="142" x2="414" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="438" y1="142" x2="428" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="452" y1="142" x2="442" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="466" y1="142" x2="456" y2="154" stroke="#6b7685" stroke-width="1.2"/><line x1="480" y1="142" x2="470" y2="154" stroke="#6b7685" stroke-width="1.2"/><ellipse cx="130" cy="141" rx="42" ry="3" fill="#000" opacity="0.18"/><ellipse cx="300" cy="141" rx="52" ry="3" fill="#000" opacity="0.18"/><line x1="170" y1="112" x2="250" y2="112" stroke="#7a5a2b" stroke-width="3"/><linearGradient id="q9-K" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#5b8fd6"/><stop offset="1" stop-color="#2a5aa0"/></linearGradient><rect x="90" y="84" width="80" height="56" rx="3" fill="url(#q9-K)" stroke="#2b2f36" stroke-width="1.5"/><rect x="93" y="87" width="74" height="5" rx="2" fill="#ffffff" opacity="0.35"/><text x="130" y="110" font-size="20" text-anchor="middle" fill="#ffffff" font-weight="700" paint-order="stroke" stroke="none" stroke-width="4" stroke-linejoin="round">K</text><text x="130" y="130" font-size="14" text-anchor="middle" fill="#ffffff" font-weight="500" paint-order="stroke" stroke="none" stroke-width="4" stroke-linejoin="round">2 kg</text><linearGradient id="q9-L" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#e08a5a"/><stop offset="1" stop-color="#b4532a"/></linearGradient><rect x="250" y="70" width="100" height="70" rx="3" fill="url(#q9-L)" stroke="#2b2f36" stroke-width="1.5"/><rect x="253" y="73" width="94" height="5" rx="2" fill="#ffffff" opacity="0.35"/><text x="300" y="103" font-size="20" text-anchor="middle" fill="#ffffff" font-weight="700" paint-order="stroke" stroke="none" stroke-width="4" stroke-linejoin="round">L</text><text x="300" y="123" font-size="14" text-anchor="middle" fill="#ffffff" font-weight="500" paint-order="stroke" stroke="none" stroke-width="4" stroke-linejoin="round">3 kg</text><g data-ciz-adim="0" data-ciz-sure="500"><line x1="350" y1="105" x2="438" y2="105" stroke="#1d2733" stroke-width="3.5" stroke-linecap="round"/><polygon points="450,105 437,110.85 437,99.15" fill="#1d2733"/></g><text x="400" y="92" font-size="16" text-anchor="middle" fill="#1d2733" font-weight="700" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">F = 20 N</text><g data-ciz-adim="2" data-ciz-sure="500"><line x1="170" y1="112" x2="210" y2="112" stroke="#c62828" stroke-width="4" stroke-linecap="round"/><polygon points="222,112 209,117.85 209,106.15" fill="#c62828"/></g><text x="198" y="101" font-size="18" text-anchor="middle" fill="#c62828" font-weight="700" font-style="italic" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round" data-ciz-adim="2" data-ciz-gecikme="300">T</text><text x="265" y="30" font-size="13" text-anchor="middle" fill="#6b7685" font-weight="500" paint-order="stroke" stroke="#ffffff" stroke-width="4" stroke-linejoin="round">Sürtünmesiz yatay düzlem</text></svg>', '[{"harf":"A","metin":"4","gerekce":"4 sistemin ivmesidir (m/s²), kuvvet değildir. İp gerilmesi için K bloğunun kütlesiyle çarpmak gerekir."},{"harf":"B","metin":"8"},{"harf":"C","metin":"10","gerekce":"Kuvvet bloklara eşit paylaşılmaz. İp yalnızca K bloğunu hızlandırır; payı K bloğunun kütlesiyle orantılıdır."},{"harf":"D","metin":"12","gerekce":"3 × 4 = 12, L bloğunu hızlandıran net kuvvettir. İp ise K bloğunu çeker: T = 2 × 4."},{"harf":"E","metin":"20","gerekce":"İp F kuvvetini olduğu gibi iletmez. F iki bloğu birlikte hızlandırır, ip yalnızca K bloğunu."}]'::jsonb, 'B',
  '[{"metin":"Bloklar birlikte hareket eder. Sistemin ivmesi: $a = \\dfrac{F}{m_K + m_L} = \\dfrac{20}{2 + 3} = 4$ m/s²."},{"metin":"K bloğunun serbest cisim diyagramında yatay doğrultuda yalnızca ip gerilmesi $T$ vardır."},{"metin":"$T = m_K a = 2 \\times 4 = 8$ N. Cevap B."}]'::jsonb, 3, false, 'Örnek soru.', true)
on conflict (id) do update set tur = excluded.tur, govde = excluded.govde, sekil_svg = excluded.sekil_svg,
  secenekler = excluded.secenekler, dogru_cevap = excluded.dogru_cevap, cozum_adimlari = excluded.cozum_adimlari,
